import { FixedSizeList } from 'react-window';

interface Row {
  id: number;
  name: string;
  email: string;
}

function VirtualizedTable({ rows }: { rows: Row[] }) {
  const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => (
    <div style={style} className="table-row">
      <span>{rows[index].name}</span>
      <span>{rows[index].email}</span>
    </div>
  );

  return (
    <FixedSizeList
      height={500}
      itemCount={rows.length}
      itemSize={40}
      width="100%"
    >
      {Row}
    </FixedSizeList>
  );
}

import { Virtuoso } from 'react-virtuoso';

interface Message {
  id: string;
  text: string;
  timestamp: number;
}

function ChatFeed({ messages }: { messages: Message[] }) {
  return (
    <Virtuoso
      style={{ height: 600 }}
      totalCount={messages.length}
      itemContent={(index) => (
        <div className="message" key={messages[index].id}>
          <strong>{messages[index].text}</strong>
          <time>{new Date(messages[index].timestamp).toLocaleTimeString()}</time>
        </div>
      )}
    />
  );
}
